#!/usr/bin/env python3
"""Imports a clip generated by PixelLab (frames f_00.png, f_01.png... in a folder) for a fighter.

    python3 scripts/import_clip.py FIGHTER ANIM FRAMES_DIR --anchor AX AY --pxh P [--loop] [--fps 15]
                                   [--impact N] [--keep-first] [--only 1-8] [--drop PX]

- FIGHTER: the fighter's id (p01, p02...); ANIM: the clip's name, as in sheetName() of
  src/game/fighter_art.cpp: a state ("idle", "run", "roll"...), a move ("jab", "fsmash", "nspecial", "ultimate"...)
  or a move with a picked-up weapon ("w0_jab", "w1_jab");
- FRAMES_DIR: what PixelLab returned. f_00.png is the frame it was given (left out unless --keep-first), the
  others the generated ones; --only A-B keeps that range;
- --anchor AX AY: where the fighter stands in the frames (its position x, the ground y), --pxh P: frame pixels per
  fighter height. PixelLab keeps the canvas of the frame it is given, so these are the ones of that frame;
- --loop: a looping clip (idle, walk...) played at --fps images per second; otherwise the clip is spread over the
  state or the move, and --impact N (from 0, after the frames left out) is the frame held while the blow is out
  (several blows: --impact 3,9, one frame per hitbox window of the move, in order);
- --drop PX: the first frame is drawn PX lower, easing back to the anchor by the last (the ledge climb starts from
  the hands on the ledge and ends standing).

The frames are cropped to their common box (the anchor follows) and saved as one paletted strip,
assets/sprites/FIGHTER_ANIM.png, with its line in assets/sprites/sheets.txt:
"sheet FIGHTER ANIM frames frame_w frame_h anchor_x anchor_y px_per_height loop impact fps".
"""
import argparse
import os

import numpy as np
from PIL import Image


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("fighter")
    ap.add_argument("anim")
    ap.add_argument("frames_dir")
    ap.add_argument("--anchor", type=float, nargs=2, required=True, metavar=("AX", "AY"))
    ap.add_argument("--pxh", type=float, required=True)
    ap.add_argument("--loop", action="store_true")
    ap.add_argument("--fps", type=float, default=15.0)
    ap.add_argument("--impact", default="-1", help="frame where the blow lands, or one per blow: 7,22")
    ap.add_argument("--keep-first", action="store_true")
    ap.add_argument("--only", default=None, help="range of frames to keep, e.g. 1-8")
    ap.add_argument("--drop", type=float, default=0.0,
                    help="px: the first frame is drawn this much lower, easing to 0 by the last (the ledge climb)")
    a = ap.parse_args()

    names = sorted(f for f in os.listdir(a.frames_dir) if f.startswith("f_") and f.endswith(".png"))
    idx = [int(n[2:-4]) for n in names]
    if a.only:
        lo, hi = (int(v) for v in a.only.split("-"))
        idx = [i for i in idx if lo <= i <= hi]
    elif not a.keep_first:
        idx = [i for i in idx if i > 0] or idx
    frames = [Image.open(os.path.join(a.frames_dir, f"f_{i:02d}.png")).convert("RGBA") for i in idx]
    if not frames:
        raise SystemExit("no frames")
    w, h = frames[0].size
    # Common box of every frame (with a pixel of margin), so the strip holds no empty borders.
    boxes = [f.getbbox() for f in frames if f.getbbox()]
    x0 = max(0, min(b[0] for b in boxes) - 1)
    y0 = max(0, min(b[1] for b in boxes) - 1)
    x1 = min(w, max(b[2] for b in boxes) + 1)
    y1 = min(h, max(b[3] for b in boxes) + 1)
    fw, fh = x1 - x0, y1 - y0
    strip = Image.new("RGBA", (fw * len(frames), fh), (0, 0, 0, 0))
    for k, f in enumerate(frames):
        strip.alpha_composite(f.crop((x0, y0, x1, y1)), (k * fw, 0))
    # Pixel art: hard alpha, few colours -> a paletted PNG (lossless when there are at most 255 colours).
    alpha = strip.getchannel("A").point(lambda v: 255 if v >= 128 else 0)
    strip.putalpha(alpha)
    colours = strip.getcolors(1 << 20) or []
    opaque = {c[1][:3] for c in colours if c[1][3] > 0}
    root = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
    out_dir = os.path.join(root, "assets", "sprites")
    os.makedirs(out_dir, exist_ok=True)
    out = os.path.join(out_dir, f"{a.fighter}_{a.anim}.png")
    if len(opaque) <= 255:  # index 0 is the transparent colour, then every opaque colour as it is
        arr = np.asarray(strip)
        cols = sorted(opaque)
        key = (arr[..., 0].astype(np.uint32) << 16) | (arr[..., 1].astype(np.uint32) << 8) | arr[..., 2]
        keys = np.array([(c[0] << 16) | (c[1] << 8) | c[2] for c in cols], dtype=np.uint32)
        idx = np.searchsorted(keys, key).astype(np.uint8) + 1
        idx[arr[..., 3] == 0] = 0
        p = Image.fromarray(idx, "P")
        palette = [0, 0, 0] + [v for c in cols for v in c]
        p.putpalette(palette + [0] * (768 - len(palette)))
        p.save(out, optimize=True, transparency=0)
    else:
        strip.save(out, optimize=True)
    keys = [int(v) for v in str(a.impact).split(",") if v.strip().lstrip("-").isdigit()]
    keys = [k for k in keys if 0 <= k < len(frames)]
    impact = ",".join(str(k) for k in keys) if keys else "-1"
    index = os.path.join(out_dir, "sheets.txt")
    lines = []
    if os.path.exists(index):
        lines = [l for l in open(index).read().splitlines()
                 if l.strip() and not l.startswith(f"sheet {a.fighter} {a.anim} ")]
    header = ("# Generated by scripts/import_clip.py: "
              "sheet fighter anim frames frame_w frame_h anchor_x anchor_y px_per_height loop impact fps [drop]")
    lines = [l for l in lines if not l.startswith("#")]
    lines.insert(0, header)
    lines.append(f"sheet {a.fighter} {a.anim} {len(frames)} {fw} {fh} {a.anchor[0] - x0:.1f} {a.anchor[1] - y0:.1f} "
                 f"{a.pxh:.1f} {1 if a.loop else 0} {impact} {a.fps:g}" + (f" {a.drop:.1f}" if a.drop else ""))
    body = sorted(lines[1:])
    open(index, "w").write("\n".join([header] + body) + "\n")
    print(f"{a.fighter} {a.anim}: {len(frames)} frames {fw}x{fh}, {len(opaque)} colours, "
          f"{os.path.getsize(out) // 1024} KB")


if __name__ == "__main__":
    main()
